const trigger = $input.first().json.body || $input.first().json;
const userMsg = trigger.user_message || '';
const assistantMsg = trigger.assistant_message || '';
const sessionId = trigger.session_id || '';

const requestBody = {
  requests: [
    {
      type: 'execute',
      stmt: {
        sql: "SELECT content FROM prompts WHERE key = 'emotion_tracker' LIMIT 1"
      }
    },
    {
      type: 'execute',
      stmt: {
        sql: 'SELECT emotion, intensity, created_at FROM mood_log WHERE session_id = ? ORDER BY created_at DESC LIMIT 10',
        args: [{ type: 'text', value: sessionId }]
      }
    }
  ]
};

return [{ json: { requestBody, userMsg, assistantMsg, sessionId } }];

const dbResult = $input.first().json;
const prevData = $('Build DB Request').first().json;

const results = dbResult.results || [];
const parseRows = (result) => {
  if (!result || !result.response || !result.response.result) return [];
  const cols = result.response.result.columns || result.response.result.cols || [];
  const rows = result.response.result.rows || [];
  return rows.map(row => {
    const obj = {};
    cols.forEach((col, i) => {
      const cell = row[i];
      obj[col.name] = (cell && typeof cell === 'object' && 'value' in cell) ? cell.value : cell;
    });
    return obj;
  });
};

const emotionPrompt = parseRows(results[0])[0]?.content || '';
const moodHistory = parseRows(results[1]);

const historyStr = moodHistory.map(m => m.emotion + '(' + m.intensity + ') at ' + m.created_at).join('\n') || 'No prior mood data.';

const messages = [
  { role: 'system', content: emotionPrompt },
  { role: 'user', content: 'MOOD HISTORY:\n' + historyStr + '\n\nNEW CONVERSATION:\nUser: ' + prevData.userMsg + '\nClara: ' + prevData.assistantMsg + '\n\nAnalyze the emotions. Return JSON only.' }
];

return [{ json: { messages, sessionId: prevData.sessionId } }];

const llmResponse = $input.first().json;
const content = (llmResponse.choices && llmResponse.choices[0] && llmResponse.choices[0].message && llmResponse.choices[0].message.content) || '';
const prevData = $('Build Emotion Prompt').first().json;
const sessionId = prevData.sessionId;

let raw;
try {
  const jsonMatch = content.match(/\{[\s\S]*\}/);
  raw = JSON.parse(jsonMatch ? jsonMatch[0] : content);
} catch (e) {
  raw = {};
}

// Normalize from any format into userEmotion/claraEmotion
let userEmotion = null, userIntensity = 0.5, claraEmotion = null, claraIntensity = 0.5;
const intMap = { barely: 0.2, mild: 0.4, moderate: 0.6, high: 0.8, strong: 0.9, low: 0.3, medium: 0.5 };

function parseIntensity(v) {
  if (typeof v === 'number') return v;
  if (typeof v === 'string') return intMap[v.toLowerCase()] || 0.5;
  return 0.5;
}

// Format 0: flat with primary_emotion -- { primary_emotion: 'sadness', intensity: 'moderate' }
if (raw.primary_emotion && !raw.user_emotion) {
  userEmotion = raw.primary_emotion;
  userIntensity = parseIntensity(raw.intensity);
  if (raw.clara_response_analysis) {
    claraEmotion = raw.clara_response_analysis.primary_emotion || raw.clara_response_analysis.emotion || null;
    claraIntensity = parseIntensity(raw.clara_response_analysis.intensity || raw.clara_response_analysis.confidence);
  }
}
// Format 1: flat — { user_emotion: '...', clara_emotion: '...' }
if (raw.user_emotion) {
  userEmotion = raw.user_emotion;
  userIntensity = parseIntensity(raw.user_intensity);
  claraEmotion = raw.clara_emotion || null;
  claraIntensity = parseIntensity(raw.clara_intensity);
}
// Format 2: nested — { user: { primary_emotion: '...' }, clara: { ... } }
else if (raw.user && typeof raw.user === 'object') {
  userEmotion = raw.user.primary_emotion || raw.user.emotion || raw.user.feeling || null;
  userIntensity = parseIntensity(raw.user.intensity);
  if (raw.clara) {
    claraEmotion = raw.clara.primary_emotion || raw.clara.emotion || raw.clara.feeling || null;
    claraIntensity = parseIntensity(raw.clara.intensity);
  }
}
// Format 3: analysis array — { conversation_analysis: { detected_emotions: [...] } }
else if (raw.conversation_analysis && raw.conversation_analysis.detected_emotions) {
  const emotions = raw.conversation_analysis.detected_emotions;
  if (emotions.length > 0) {
    userEmotion = emotions[0].emotion || emotions[0].name || null;
    userIntensity = parseIntensity(emotions[0].confidence || emotions[0].intensity);
  }
  if (emotions.length > 1) {
    claraEmotion = emotions[1].emotion || emotions[1].name || null;
    claraIntensity = parseIntensity(emotions[1].confidence || emotions[1].intensity);
  }
}
// Format 4: user_emotions — object or array
else if (raw.user_emotions) {
  if (Array.isArray(raw.user_emotions)) {
    userEmotion = raw.user_emotions[0]?.emotion || raw.user_emotions[0]?.name || null;
    userIntensity = parseIntensity(raw.user_emotions[0]?.intensity || raw.user_emotions[0]?.confidence);
  } else if (raw.user_emotions.primary) {
    // { user_emotions: { primary: ['fatigue', 'stress'], intensity: 'moderate-high' } }
    userEmotion = Array.isArray(raw.user_emotions.primary) ? raw.user_emotions.primary[0] : raw.user_emotions.primary;
    userIntensity = parseIntensity(raw.user_emotions.intensity);
  }
  if (raw.clara_emotions) {
    if (Array.isArray(raw.clara_emotions)) {
      claraEmotion = raw.clara_emotions[0]?.emotion || raw.clara_emotions[0]?.name || null;
    } else if (raw.clara_emotions.primary) {
      claraEmotion = Array.isArray(raw.clara_emotions.primary) ? raw.clara_emotions.primary[0] : raw.clara_emotions.primary;
    }
  }
}
// Format 5: fallback — search for any emotion-like field
else {
  const flat = JSON.stringify(raw).toLowerCase();
  const emotions = ['happy','sad','angry','jealous','tired','excited','anxious','calm','playful','frustrated','content','lonely','grateful','annoyed','nervous','affectionate','vulnerable','confident'];
  for (const e of emotions) {
    if (flat.includes(e)) { userEmotion = e; break; }
  }
}

const requests = [];
if (userEmotion) {
  requests.push({
    type: 'execute',
    stmt: {
      sql: 'INSERT INTO mood_log (session_id, emotion, intensity, trigger_msg) VALUES (?, ?, ?, ?)',
      args: [
        { type: 'text', value: sessionId },
        { type: 'text', value: userEmotion },
        { type: 'float', value: userIntensity },
        { type: 'text', value: 'user' }
      ]
    }
  });
}
if (claraEmotion) {
  requests.push({
    type: 'execute',
    stmt: {
      sql: 'INSERT INTO mood_log (session_id, emotion, intensity, trigger_msg) VALUES (?, ?, ?, ?)',
      args: [
        { type: 'text', value: sessionId },
        { type: 'text', value: claraEmotion },
        { type: 'float', value: claraIntensity },
        { type: 'text', value: 'clara' }
      ]
    }
  });
}

return [{ json: { requestBody: { requests }, debug: { userEmotion, claraEmotion, rawKeys: Object.keys(raw) } } }];
